const body = $input.first().json.body;
const entry = body?.entry?.[0];
const change = entry?.changes?.[0]?.value;
const message = change?.messages?.[0];
const contact = change?.contacts?.[0];

if (!message) return [{ json: { skip: true } }];

const base = { skip: false, isInteractive: false, phoneNumber: message.from, phoneNumberId: change.metadata.phone_number_id, contactName: contact?.profile?.name || 'Student' };

if (message.type === 'interactive') {
  const r = message.interactive?.list_reply || message.interactive?.button_reply;
  return [{ json: { ...base, isInteractive: true, selectionId: r?.id } }];
}

return [{ json: { ...base, query: message.text?.body } }];

const input = $input.first().json;
const id = (input.selectionId || '').trim();

// User selected section only (SECTION|Sec-SD) - send day menu
if (id.startsWith('SECTION|')) {
  const tab = id.replace('SECTION|', '');
  const labels = { 'Sec-SD': 'Software Dev', 'Sec-SA': 'AI & ML', 'Sec-SC': 'Cyber Security', 'Sec-SI': 'IBM', 'Sec-SX': 'Xebia', 'Sec-SK': 'Section SK' };
  return [{ json: { ...input, section: tab, sectionName: labels[tab] || tab, hasDay: false } }];
}

// User selected day (Sec-SD|Monday) - get timetable
const parts = id.split('|');
if (parts.length === 2) {
  const labels = { 'Sec-SD': 'Software Dev', 'Sec-SA': 'AI & ML', 'Sec-SC': 'Cyber Security', 'Sec-SI': 'IBM', 'Sec-SX': 'Xebia', 'Sec-SK': 'Section SK' };
  return [{ json: { ...input, section: parts[0], sectionName: labels[parts[0]] || parts[0], day: parts[1], hasDay: true } }];
}

return [{ json: { ...input, section: null } }];

const input = $input.first().json;
const query = (input.query || '').toLowerCase();

const sectionMap = [
  { keywords: ['sd'], tab: 'Sec-SD', name: 'Software Dev' },
  { keywords: ['aiml', 'ai', 'ml'], tab: 'Sec-SA', name: 'AI & ML' },
  { keywords: ['cyber', 'cys'], tab: 'Sec-SC', name: 'Cyber Security' },
  { keywords: ['ibm'], tab: 'Sec-SI', name: 'IBM' },
  { keywords: ['xebia'], tab: 'Sec-SX', name: 'Xebia' },
  { keywords: ['sk', 'section sk'], tab: 'Sec-SK', name: 'Section SK' }
];

let section = null, sectionName = null;
for (const m of sectionMap) { if (m.keywords.some(k => query.includes(k))) { section = m.tab; sectionName = m.name; break; } }

const dayMap = { 'monday': 'Monday', 'tuesday': 'Tuesday', 'wednesday': 'Wednesday', 'thursday': 'Thursday', 'friday': 'Friday', 'saturday': 'Saturday' };
let day = null;
for (const [k,v] of Object.entries(dayMap)) { if (query.includes(k)) { day = v; break; } }

return [{ json: { ...input, section, sectionName, day, needsSection: !section } }];

const rows = $input.all().map(i => i.json);
const data = $('Query Preprocessor').first().json;

const dayRow = rows.find(r => r['Day/Time']?.toLowerCase() === data.day?.toLowerCase());

if (!dayRow || !data.day) return [{ json: { response: 'No timetable found for ' + (data.day || 'this day') } }];

let text = `📅 *${data.day} - ${data.sectionName}*\n\n`;
const slots = [{ col: 'Lecture 1 (8.00-8.50)', time: '8:00-8:50' },{ col: 'Lecture 2 (8.50-9.40)', time: '8:50-9:40' },{ col: 'Lecture 3 (9.40-10.30)', time: '9:40-10:30' },{ col: 'Lecture 4 (10.30-11.20)', time: '10:30-11:20' },{ col: 'Lecture 5 (11.20-12.05)', time: '11:20-12:05' },{ col: 'Lecture 6 (12.05-12.50)', time: '12:05-12:50' }];

for (const slot of slots) {
  const val = (dayRow[slot.col] || '').trim();
  text += (val && val !== 'N/A') ? `⏰ ${slot.time}\n📚 ${val}\n\n` : `⏰ ${slot.time}\n🆓 Free\n\n`;
}

return [{ json: { response: text } }];
